import { writeFile } from 'node:fs/promises';
import dynamicIconImports from 'lucide-react/dynamicIconImports.mjs';
// Use the installed package's complete registry, including its supported aliases.
// Regenerated by postinstall whenever the lockfile/package version changes.
const names = Object.keys(dynamicIconImports).sort();
if (!names.length) throw new Error('The installed Lucide icon registry is empty.');
await writeFile(new URL('../lib/lucide-icon-names.json', import.meta.url), `${JSON.stringify(names, null, 2)}\n`);
console.log(`Lucide catalog: ${names.length} icons`);
